168	      // included by either Swift Package Manager or Cocoapods. This can happen
169	      // when a plugin doesn't have native platform code.
170	      // For example, image_picker_macos only uses dart code.
171	      if (!swiftPackageManagerCompatible && !cocoaPodsCompatible) {
172	        continue;
